import type { FilterStateProps } from "../lib/filter";
import type { ReactNode, SelectHTMLAttributes } from "react";
import { cn } from "../lib/utils";
import { fieldClass } from "./Input";
import { IconCheck, IconChevronDown, IconSpinner, IconFilters, IconClose } from "../icons";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "../primitives/dropdown-menu";

export type SelectOption = { value: string | number; label: string; icon?: ReactNode };

export type SelectProps = FilterStateProps & {
    /** Optional clear action for filters whose neutral value is not empty/all. */
    onClearFilter?: () => void;
    options: SelectOption[];
    value?: string | number;
    onChange?: (value: string) => void;
    placeholder?: string;
    /** Leading icon when the selected option does not provide its own. */
    icon?: ReactNode;
    label?: string;
    /** Ação inline ao lado do label (ex.: "Criar novo"). */
    labelAction?: { label: string; onClick: () => void };
    error?: string;
    /** Desabilita o campo e troca o chevron por spinner (opções carregando). */
    loading?: boolean;
    disabled?: boolean;
    className?: string;
};

/** Select com dropdown estilizado do DS (não usa o popup nativo do SO). */
export function Select({ options, value, onChange, placeholder = "Selecionar", icon, label, labelAction, error, loading, disabled, className, filterActive, onClearFilter }: SelectProps) {
    const neutralOption = options.find((opt) => opt.value === "" || opt.value === "all");
    const clearFilter = onClearFilter ?? (neutralOption && onChange ? () => onChange(String(neutralOption.value)) : undefined);
    const selected = options.find((opt) => String(opt.value) === String(value ?? ""));
    const leadingIcon = selected?.icon ?? icon ?? (filterActive ? <IconFilters size={14} /> : null);

    const control = (
        // Modal de propósito: o Select nunca abre diálogo (o motivo do modal=false no DropdownMenu), e
        // não modal ele fecha no mesmo instante quando está dentro de um Dialog (o foco preso do diálogo
        // puxa o foco de volta e o menu entende como clique fora).
        <DropdownMenu modal>
            <DropdownMenuTrigger asChild disabled={disabled || loading}>
                <button
                    type="button"
                    data-filter-active={filterActive || undefined}
                    aria-invalid={!!error || undefined}
                    aria-label={filterActive ? `${label ?? "Filtro"}: ${selected?.label ?? placeholder} — aplicado` : undefined}
                    title={filterActive ? `Filtro ativo: ${selected?.label ?? placeholder}` : undefined}
                    className={cn(
                        fieldClass, "select-none",
                        "flex cursor-pointer items-center justify-between gap-2 text-left",
                        "data-[state=open]:border-brand data-[state=open]:ring-2 data-[state=open]:ring-brand/25",
                        !selected && "text-muted-foreground/80",
                        error && "border-destructive focus-visible:border-destructive focus-visible:ring-destructive/20",
                        className
                    )}
                >
                    {leadingIcon && <span className="inline-flex shrink-0 items-center" aria-hidden="true">{leadingIcon}</span>}
                    <span className="min-w-0 flex-1 truncate">{selected?.label ?? placeholder}</span>
                    {loading ? (
                        <IconSpinner size={13} className="shrink-0 animate-spin text-muted-foreground" />
                    ) : (
                        <IconChevronDown size={12} className="shrink-0 text-muted-foreground" />
                    )}
                </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
                align="start"
                className="max-h-[min(22rem,var(--radix-dropdown-menu-content-available-height))]"
                style={{ minWidth: "var(--radix-dropdown-menu-trigger-width)" }}
            >
                {filterActive && clearFilter && <DropdownMenuItem onSelect={clearFilter} className="mb-1 gap-2 border-b border-border pb-2 font-semibold text-brand">
                    <IconClose size={13} /> Limpar filtro
                </DropdownMenuItem>}
                {options.map((opt) => {
                    const isSelected = String(opt.value) === String(value ?? "");
                    return (
                        <DropdownMenuItem
                            key={opt.value}
                            onClick={() => onChange?.(String(opt.value))}
                            className={cn("justify-between", isSelected && "font-semibold text-brand")}
                        >
                            <span className="flex min-w-0 items-center gap-2">
                                {opt.icon && <span className="inline-flex shrink-0 items-center" aria-hidden="true">{opt.icon}</span>}
                                <span className="truncate">{opt.label}</span>
                            </span>
                            {isSelected && <IconCheck size={13} className="shrink-0 text-brand" />}
                        </DropdownMenuItem>
                    );
                })}
            </DropdownMenuContent>
        </DropdownMenu>
    );

    if (!label && !error) return control;

    return (
        <div className="flex w-full min-w-0 flex-col gap-1.5">
            {label && (
                <div className="flex items-center justify-between">
                    <span className="text-[12px] font-semibold text-foreground/80">{label}</span>
                    {labelAction && (
                        <button
                            type="button"
                            onClick={labelAction.onClick}
                            className="cursor-pointer text-[12px] font-semibold text-brand transition-opacity hover:opacity-80"
                        >
                            {labelAction.label}
                        </button>
                    )}
                </div>
            )}
            {control}
            {error && <span className="text-[12px] font-medium text-destructive">{error}</span>}
        </div>
    );
}

export type NativeSelectProps = SelectHTMLAttributes<HTMLSelectElement> & FilterStateProps & {
    options: SelectOption[];
    placeholder?: string;
};

/** Select nativo estilizado (popup do SO): útil em mobile e formulários longos. */
export function NativeSelect({ className, options, placeholder, filterActive, ...props }: NativeSelectProps) {
    return (
        <div className={cn("relative flex items-center", className)}>
            <select data-filter-active={filterActive || undefined} title={filterActive ? "Filtro ativo" : props.title} className={cn(fieldClass, "select-none", "cursor-pointer appearance-none pr-8")} {...props}>
                {placeholder && (
                    <option value="" disabled>
                        {placeholder}
                    </option>
                )}
                {options.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                        {opt.label}
                    </option>
                ))}
            </select>
            <IconChevronDown size={12} className="pointer-events-none absolute right-3 text-muted-foreground" />
        </div>
    );
}
